from pathlib import Path
import json
import pandas as pd

PROJECT = Path(r"E:\quant-framework")


def _read_records(path: str) -> pd.DataFrame:
    p = Path(path)
    if not p.exists() or p.stat().st_size == 0:
        return pd.DataFrame()
    text = p.read_text(encoding="utf-8")
    if not text.strip():
        return pd.DataFrame()
    return pd.DataFrame(json.loads(text))


def _write_records(df: pd.DataFrame, path: Path) -> None:
    out = df.reset_index().rename(columns={"index": "symbol"}).copy()
    path.write_text(out.to_json(orient="records", force_ascii=False), encoding="utf-8")


def run(input, context):
    import sys
    sys.path.insert(0, str(PROJECT))
    from alphalab.strategy.config import StrategyConfig
    from alphalab.factors.technical import TechnicalFactors
    from alphalab.factors.fundamental import FundamentalFactors

    data = input.get("data_result") or {}
    strategy_path = Path(input.get("strategy_path") or data.get("strategy_path") or PROJECT / "alphalab" / "strategies" / "momentum.yaml")
    if not strategy_path.is_absolute():
        strategy_path = PROJECT / strategy_path
    cfg = StrategyConfig.from_yaml(strategy_path)
    requested = input.get("factor_names") or [f.name for f in cfg.factors]
    spec_by_name = {f.name: f for f in cfg.factors}

    bars = _read_records(data.get("bars_path", ""))
    fundamentals = _read_records(data.get("fundamentals_path", ""))
    if "date" in bars:
        bars["date"] = pd.to_datetime(bars["date"])

    parts = []
    tech = TechnicalFactors()
    fund = FundamentalFactors()
    data_by_symbol = {}
    if not bars.empty and "symbol" in bars:
        data_by_symbol = {sym: frame.sort_values("date").reset_index(drop=True) for sym, frame in bars.groupby("symbol")}

    for name in requested:
        source = spec_by_name.get(name).source if name in spec_by_name else None
        if source == "fundamental" or (source is None and name in fund.available_factors):
            series = fund.compute(name, fundamentals) if not fundamentals.empty else pd.Series(dtype=float, name=name)
        else:
            series = tech.compute(name, data_by_symbol) if data_by_symbol else pd.Series(dtype=float, name=name)
        if not series.empty:
            parts.append(series.rename(name))

    factors = pd.concat(parts, axis=1) if parts else pd.DataFrame()
    run_dir = Path(data.get("run_dir") or PROJECT / "data" / "app" / "pipeline_runs" / (data.get("run_id") or "manual"))
    run_dir.mkdir(parents=True, exist_ok=True)
    factors_path = run_dir / "factors.json"
    _write_records(factors, factors_path)

    return {
        "stage": "compute_factor",
        "run_id": data.get("run_id"),
        "run_dir": str(run_dir),
        "strategy_path": str(strategy_path),
        "factor_names": requested,
        "factors_path": str(factors_path),
        "counts": {"symbols_with_scores": int(len(factors)), "factor_columns": int(len(factors.columns))},
        "factor_specs": [{"name": f.name, "source": f.source, "direction": f.direction, "weight": f.weight} for f in cfg.factors if f.name in requested],
        "sample": factors.head(10).reset_index().rename(columns={"index": "symbol"}).astype(str).to_dict(orient="records"),
        "upstream": {"data_counts": data.get("counts", {})},
    }
